CREATE TABLE IF NOT EXISTS external_venue_ref (
    id BIGSERIAL PRIMARY KEY,
    provider TEXT NOT NULL,
    external_id TEXT NOT NULL,
    venue_id BIGINT NOT NULL REFERENCES venue(id),
    last_seen_at TIMESTAMPTZ NOT NULL,
