);

CREATE TABLE IF NOT EXISTS external_artist_ref (
    id BIGSERIAL PRIMARY KEY,
    provider TEXT NOT NULL,
    external_id TEXT NOT NULL,
    artist_id BIGINT NOT NULL REFERENCES social_artist_profile(id),
