CREATe TABLE "workflow_definition"("id" uuid PRIMARY KEY UNIQUE DEFAULT gen_random_uuid(),"code" VARCHAR NOT NULL,"name_es" VARCHAR NOT NULL,"name_en" VARCHAR NOT NULL,"description_es" VARCHAR NULL,"description_en" VARCHAR NULL,"sensitive" BOOLEAN NOT NULL DEFAULT False,"public_read" BOOLEAN NOT NULL DEFAULT False,"cache_revision" INT8 NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT True,"created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"version" INT8 NOT NULL DEFAULT 1);
ALTER TABLE "workflow_definition" ADD CONSTRAINT "unique_workflow_definition_code" UNIQUE("code");
CREATe TABLE "workflow_state"("id" uuid PRIMARY KEY UNIQUE DEFAULT gen_random_uuid(),"workflow_id" uuid NOT NULL,"code" VARCHAR NOT NULL,"name_es" VARCHAR NOT NULL,"name_en" VARCHAR NOT NULL,"description_es" VARCHAR NULL,"description_en" VARCHAR NULL,"sort_order" INT8 NOT NULL DEFAULT 0,"terminal" BOOLEAN NOT NULL DEFAULT False,"active" BOOLEAN NOT NULL DEFAULT True,"created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"version" INT8 NOT NULL DEFAULT 1);
ALTER TABLE "workflow_state" ADD CONSTRAINT "unique_workflow_state_code" UNIQUE("workflow_id","code");
