CREATe TABLE "workflow_transition"("id" uuid PRIMARY KEY UNIQUE DEFAULT gen_random_uuid(),"workflow_id" uuid NOT NULL,"from_state_id" uuid NOT NULL,"to_state_id" uuid NOT NULL,"required_permission_id" uuid NULL,"requires_review" BOOLEAN NOT NULL DEFAULT False,"requires_distinct_approver" BOOLEAN NOT NULL DEFAULT False,"effective_from" TIMESTAMP WITH TIME ZONE NULL,"effective_until" TIMESTAMP WITH TIME ZONE NULL,"active" BOOLEAN NOT NULL DEFAULT True,"created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"created_by" INT8 NULL,"version" INT8 NOT NULL DEFAULT 1);
ALTER TABLE "workflow_transition" ADD CONSTRAINT "unique_workflow_transition" UNIQUE("workflow_id","from_state_id","to_state_id");
