alidation_run item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_import_plan item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_import_run item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_export item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_job item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_default_state default_state WHERE default_state.state_id=OLD.id AND default_state.active) OR EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.active AND (transition.from_state_id=OLD.id OR transition.to_state_id=OLD.id)) OR EXISTS (SELECT 1 FROM workflow_state_capability capability WHERE capability.state_id=OLD.id AND capability.enabled)) THEN RAISE EXCEPTION 'a referenced workflow state cannot be deactivated' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
