CREATE INDEX IF NOT EXISTS ix_pipeline_workflow_binding_active ON pipeline_workflow_binding (workflow_id, service_offering_id) WHERE active;
CREATE INDEX IF NOT EXISTS ix_pipeline_card_canonical_board ON pipeline_card (service_offering_id, workflow_state_id, sort_order, created_at);
CREATE INDEX IF NOT EXISTS ix_workflow_state_capability_lookup ON workflow_state_capability (state_id, capability_code) WHERE enabled;
CREATE UNIQUE INDEX IF NOT EXISTS uq_workflow_active_initial_state ON workflow_default_state (workflow_id, context) WHERE active;
CREATE OR REPLACE FUNCTION catalog_version_workflow_definition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.code,NEW.name_es,NEW.name_en,NEW.description_es,NEW.description_en,NEW.sensitive,NEW.public_read,NEW.active) IS DISTINCT FROM ROW(OLD.code,OLD.name_es,OLD.name_en,OLD.description_es,OLD.description_en,OLD.sensitive,OLD.public_read,OLD.active) THEN NEW.updated_at=CURRENT_TIMESTAMP; NEW.version=GREATEST(NEW.version,OLD.version+1); NEW.cache_revision=GREATEST(NEW.cache_revision,OLD.cache_revision+1); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_version_workflow_definition ON workflow_definition;
CREATE TRIGGER catalog_version_workflow_definition BEFORE UPDATE ON workflow_definition FOR EACH ROW EXECUTE FUNCTION catalog_version_workflow_definition();
CREATE OR REPLACE FUNCTION catalog_bump_workflow_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_id_value uuid; BEGIN IF TG_TABLE_NAME='workflow_state_capability' THEN SELECT workflow_id INTO workflow_id_value FROM workflow_state WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.state_id ELSE NEW.state_id END; ELSIF TG_TABLE_NAME='workflow_state' THEN workflow_id_value=CASE WHEN TG_OP='DELETE' THEN OLD.workflow_id ELSE NEW.workflow_id END; ELSE workflow_id_value=CASE WHEN TG_OP='DELETE' THEN OLD.workflow_id ELSE NEW.workflow_id END; END IF; UPDATE workflow_definition SET cache_revision=cache_revision+1, updated_at=CURRENT_TIMESTAMP WHERE id=workflow_id_value; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_bump_workflow_revision ON workflow_state;
CREATE TRIGGER catalog_bump_workflow_revision AFTER INSERT OR UPDATE OR DELETE ON workflow_state FOR EACH ROW EXECUTE FUNCTION catalog_bump_workflow_revision();
DROP TRIGGER IF EXISTS catalog_bump_workflow_revision ON workflow_transition;
CREATE TRIGGER catalog_bump_workflow_revision AFTER INSERT OR UPDATE OR DELETE ON workflow_transition FOR EACH ROW EXECUTE FUNCTION catalog_bump_workflow_revision();
DROP TRIGGER IF EXISTS catalog_bump_workflow_revision ON workflow_default_state;
CREATE TRIGGER catalog_bump_workflow_revision AFTER INSERT OR UPDATE OR DELETE ON workflow_default_state FOR EACH ROW EXECUTE FUNCTION catalog_bump_workflow_revision();
