CREATE OR REPLACE FUNCTION catalog_validate_input_row_instrument() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.instrument IS NOT NULL THEN RAISE EXCEPTION 'input rows require instrument_id; copied instrument values are migration evidence only' USING ERRCODE='23514'; END IF; IF NEW.instrument_id IS NULL OR NOT EXISTS (SELECT 1 FROM instrument item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='instruments' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.code='published' AND state.active WHERE item.id=NEW.instrument_id AND item.active AND item.deprecated_at IS NULL) THEN RAISE EXCEPTION 'input row requires an active published instrument' USING ERRCODE='23514'; END IF; IF NEW.mic_id IS NULL OR NOT EXISTS (SELECT 1 FROM asset item WHERE item.id=NEW.mic_id AND item.status='Active') THEN RAISE EXCEPTION 'input row requires an active microphone or DI asset' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
