CREATE TRIGGER live_session_musician_instrument_integrity BEFORE INSERT OR UPDATE OF instrument, role, instrument_id ON live_session_musician FOR EACH ROW EXECUTE FUNCTION catalog_validate_live_session_musician_instrument();
