CREATE TRIGGER security_audit_immutable BEFORE UPDATE OR DELETE ON security_audit_event FOR EACH ROW EXECUTE FUNCTION catalog_audit_is_immutable();
CREATE OR REPLACE FUNCTION catalog_validate_workflow_transition() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE from_workflow uuid; to_workflow uuid; BEGIN SELECT workflow_id INTO from_workflow FROM workflow_state WHERE id=NEW.from_state_id AND active; SELECT workflow_id INTO to_workflow FROM workflow_state WHERE id=NEW.to_state_id AND active; IF from_workflow IS DISTINCT FROM NEW.workflow_id OR to_workflow IS DISTINCT FROM NEW.workflow_id THEN RAISE EXCEPTION 'workflow transition states must belong to the declared workflow' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS workflow_transition_integrity ON workflow_transition;
CREATE TRIGGER workflow_transition_integrity BEFORE INSERT OR UPDATE ON workflow_transition FOR EACH ROW EXECUTE FUNCTION catalog_validate_workflow_transition();
CREATE OR REPLACE FUNCTION catalog_validate_revision_workflow() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE expected_workflow uuid; actual_workflow uuid; BEGIN SELECT workflow_id INTO expected_workflow FROM catalog_definition WHERE id=NEW.catalog_id AND active; SELECT workflow_id INTO actual_workflow FROM workflow_state WHERE id=NEW.workflow_state_id AND active; IF expected_workflow IS NULL OR actual_workflow IS DISTINCT FROM expected_workflow THEN RAISE EXCEPTION 'catalog revision state must belong to the catalog workflow' USING ERRCODE='23514'; END IF; IF NEW.approved_by IS NOT NULL AND NEW.approved_by=NEW.created_by THEN RAISE EXCEPTION 'catalog change creators cannot approve their own change' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_revision_workflow_integrity ON catalog_revision;
CREATE TRIGGER catalog_revision_workflow_integrity BEFORE INSERT OR UPDATE ON catalog_revision FOR EACH ROW EXECUTE FUNCTION catalog_validate_revision_workflow();
CREATE OR REPLACE FUNCTION catalog_validate_slug_alias_target() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_valid boolean := false; BEGIN CASE NEW.entity_kind WHEN 'authored_content' THEN SELECT EXISTS (SELECT 1 FROM authored_content target JOIN catalog_definition catalog ON catalog.id=NEW.catalog_id AND catalog.code='authored-content' WHERE target.id=NEW.entity_id) INTO target_valid; WHEN 'record-release' THEN SELECT EXISTS (SELECT 1 FROM record_release target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; WHEN 'recording' THEN SELECT EXISTS (SELECT 1 FROM recording target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; WHEN 'recording-session' THEN SELECT EXISTS (SELECT 1 FROM recording_session target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; ELSE RAISE EXCEPTION 'unsupported catalog slug alias entity kind: %',NEW.entity_kind USING ERRCODE='23514'; END CASE; IF NOT COALESCE(target_valid,false) THEN RAISE EXCEPTION 'catalog slug alias target does not exist in its declared catalog' USING ERRCODE='23503'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_slug_alias_target_integrity ON catalog_slug_alias;
CREATE TRIGGER catalog_slug_alias_target_integrity BEFORE INSERT OR UPDATE OF catalog_id,entity_kind,entity_id ON catalog_slug_alias FOR EACH ROW EXECUTE FUNCTION catalog_validate_slug_alias_target();
UPDATE catalog_slug_alias SET entity_id=entity_id;
CREATE OR REPLACE FUNCTION security_is_coherent_emergency_administrator(candidate_party bigint) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS (SELECT 1 FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.party_id=candidate_party AND assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code))) $$;
CREATE OR REPLACE FUNCTION security_validate_grant_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_code text; actor_is_emergency boolean; BEGIN SELECT w.code INTO workflow_code FROM workflow_state s JOIN workflow_definition w ON w.id=s.workflow_id WHERE s.id=NEW.workflow_state_id AND s.active AND w.active; IF workflow_code IS DISTINCT FROM 'sensitive-publication' THEN RAISE EXCEPTION 'security grant revisions must use the sensitive publication workflow' USING ERRCODE='23514'; END IF; IF NEW.change_kind='party-role' THEN IF NEW.party_id IS NULL OR NEW.permission_id IS NOT NULL THEN RAISE EXCEPTION 'party-role revisions require party and role only' USING ERRCODE='23514'; END IF; ELSIF NEW.change_kind='role-permission' THEN IF NEW.party_id IS NOT NULL OR NEW.permission_id IS NULL THEN RAISE EXCEPTION 'role-permission revisions require role and permission only' USING ERRCODE='23514'; END IF; ELSE RAISE EXCEPTION 'unknown security grant revision kind' USING ERRCODE='23514'; END IF; IF NEW.expected_version<0 THEN RAISE EXCEPTION 'security grant expected version cannot be negative' USING ERRCODE='23514'; END IF; IF NEW.approval_mode NOT IN ('normal','emergency') THEN RAISE EXCEPTION 'invalid security revision approval mode' USING ERRCODE='23514'; END IF; IF NEW.approved_by IS NOT NULL AND NEW.approved_by=NEW.created_by THEN IF NEW.approval_mode<>'emergency' OR length(btrim(COALESCE(NEW.emergency_reason,'')))<20 THEN RAISE EXCEPTION 'security change creators require a documented emergency override to self-approve' USING ERRCODE='42501'; END IF; SELECT security_is_coherent_emergency_administrator(NEW.approved_by) INTO actor_is_emergency; IF NOT COALESCE(actor_is_emergency,FALSE) THEN RAISE EXCEPTION 'emergency override approver is not an active emergency administrator' USING ERRCODE='42501'; END IF; ELSIF NEW.approval_mode='emergency' THEN RAISE EXCEPTION 'emergency approval mode is valid only for documented self-approval' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS security_grant_revision_integrity ON security_grant_revision;
CREATE TRIGGER security_grant_revision_integrity BEFORE INSERT OR UPDATE ON security_grant_revision FOR EACH ROW EXECUTE FUNCTION security_validate_grant_revision();
CREATE OR REPLACE FUNCTION catalog_validate_replacement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_active boolean; BEGIN IF NEW.replacement_id IS NULL THEN RETURN NEW; END IF; IF NEW.replacement_id=NEW.id THEN RAISE EXCEPTION 'an item cannot replace itself' USING ERRCODE='23514'; END IF; EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE id=$1 AND active)', TG_TABLE_NAME) INTO target_active USING NEW.replacement_id; IF NOT target_active THEN RAISE EXCEPTION 'replacement target must exist and be active in %', TG_TABLE_NAME USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION catalog_prevent_hierarchy_cycle() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE has_cycle boolean; BEGIN IF NEW.parent_id IS NULL THEN RETURN NEW; END IF; IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'catalog hierarchy cannot reference itself' USING ERRCODE='23514'; END IF; EXECUTE format('WITH RECURSIVE ancestors(id,parent_id) AS (SELECT id,parent_id FROM %I WHERE id=$1 UNION ALL SELECT p.id,p.parent_id FROM %I p JOIN ancestors a ON p.id=a.parent_id) SELECT EXISTS (SELECT 1 FROM ancestors WHERE id=$2)', TG_TABLE_NAME, TG_TABLE_NAME) INTO has_cycle USING NEW.parent_id, NEW.id; IF has_cycle THEN RAISE EXCEPTION 'catalog hierarchy cycle detected in %', TG_TABLE_NAME USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['genre','instrument','service_category','content_category'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_hierarchy_cycle ON %I', table_name); EXECUTE format('CREATE TRIGGER catalog_hierarchy_cycle BEFORE INSERT OR UPDATE OF parent_id ON %I FOR EACH ROW EXECUTE FUNCTION catalog_prevent_hierarchy_cycle()', table_name); END LOOP; END $$;
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['release_type_reference','recording_type_reference','recording_session_type','service_category','service_pricing_model','service_offering','radio_auto_stop_option','appearance_mode_option','genre','instrument','event_type','booking_type','feedback_category','feedback_severity','content_category','tag','country_reference','subdivision_reference','city_reference','currency_reference','tax_rate_reference','language_reference','locale_reference','external_provider','external_provider_code','ddex_standard_version','ddex_message_type','ddex_vocabulary','ddex_code'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_replacement_integrity ON %I', table_name); EXECUTE format('CREATE TRIGGER catalog_replacement_integrity BEFORE INSERT OR UPDATE OF replacement_id ON %I FOR EACH ROW EXECUTE FUNCTION catalog_validate_replacement()', table_name); END LOOP; END $$;
CREATE OR REPLACE FUNCTION catalog_prevent_hard_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'catalog and registry rows cannot be hard-deleted; deactivate, replace, merge, or reverse instead' USING ERRCODE='55000'; END $$;
DROP TRIGGER IF EXISTS catalog_no_hard_delete ON workflow_migration_mapping;
CREATE TRIGGER catalog_no_hard_delete BEFORE DELETE ON workflow_migration_mapping FOR EACH ROW EXECUTE FUNCTION catalog_prevent_hard_delete();
CREATE OR REPLACE FUNCTION catalog_validate_radio_auto_stop_default() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.active AND NEW.scope_kind='radio-broadcast' THEN IF NEW.scope_id <> 'global' OR NEW.locale_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN radio_auto_stop_option option ON option.catalog_id=catalog.id JOIN workflow_state state ON state.id=option.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='radio_auto_stop_option' AND option.id=NEW.entity_id AND option.active AND option.deprecated_at IS NULL AND state.code='published' AND state.active) THEN RAISE EXCEPTION 'radio broadcast default must reference an active published non-deprecated radio auto-stop option'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_radio_auto_stop_default_integrity ON catalog_scoped_default;
CREATE TRIGGER catalog_radio_auto_stop_default_integrity BEFORE INSERT OR UPDATE OF catalog_id, entity_id, scope_kind, scope_id, locale_id, active ON catalog_scoped_default FOR EACH ROW EXECUTE FUNCTION catalog_validate_radio_auto_stop_default();
CREATE OR REPLACE FUNCTION catalog_prevent_active_radio_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind='radio-broadcast' AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active radio broadcast default cannot be deactivated'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_radio_auto_stop_default_deactivation ON radio_auto_stop_option;
CREATE TRIGGER catalog_radio_auto_stop_default_deactivation BEFORE UPDATE OF active ON radio_auto_stop_option FOR EACH ROW EXECUTE FUNCTION catalog_prevent_active_radio_default_deactivation();
CREATE OR REPLACE FUNCTION catalog_validate_appearance_mode_default() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.active AND NEW.scope_kind='appearance-mode' THEN IF NEW.scope_id <> 'global' OR NEW.locale_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN appearance_mode_option option ON option.catalog_id=catalog.id JOIN workflow_state state ON state.id=option.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='appearance_mode_option' AND option.id=NEW.entity_id AND option.active AND option.deprecated_at IS NULL AND state.code='published' AND state.active) THEN RAISE EXCEPTION 'appearance default must reference an active published non-deprecated appearance mode'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_appearance_mode_default_integrity ON catalog_scoped_default;
CREATE TRIGGER catalog_appearance_mode_default_integrity BEFORE INSERT OR UPDATE OF catalog_id, entity_id, scope_kind, scope_id, locale_id, active ON catalog_scoped_default FOR EACH ROW EXECUTE FUNCTION catalog_validate_appearance_mode_default();
CREATE OR REPLACE FUNCTION catalog_prevent_active_appearance_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind='appearance-mode' AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active appearance default cannot be deactivated'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_appearance_mode_default_deactivation ON appearance_mode_option;
CREATE TRIGGER catalog_appearance_mode_default_deactivation BEFORE UPDATE OF active ON appearance_mode_option FOR EACH ROW EXECUTE FUNCTION catalog_prevent_active_appearance_default_deactivation();
CREATE OR REPLACE FUNCTION catalog_validate_feedback_default() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_valid boolean := false; BEGIN IF NOT NEW.active OR NEW.scope_kind NOT IN ('feedback-category','feedback-severity') THEN RETURN NEW; END IF; IF NEW.scope_id<>'global' OR NEW.locale_id IS NOT NULL THEN RAISE EXCEPTION 'feedback defaults must use the global scope'; END IF; IF NEW.scope_kind='feedback-category' THEN SELECT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN feedback_category item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='feedback_category' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) INTO target_valid; ELSE SELECT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN feedback_severity item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='feedback_severity' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) INTO target_valid; END IF; IF NOT COALESCE(target_valid,false) THEN RAISE EXCEPTION 'feedback default must reference an active published non-deprecated option'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_feedback_default_integrity ON catalog_scoped_default;
CREATE TRIGGER catalog_feedback_default_integrity BEFORE INSERT OR UPDATE OF catalog_id, entity_id, scope_kind, scope_id, locale_id, active ON catalog_scoped_default FOR EACH ROW EXECUTE FUNCTION catalog_validate_feedback_default();
CREATE OR REPLACE FUNCTION catalog_prevent_active_feedback_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE expected_scope text; BEGIN expected_scope := CASE TG_TABLE_NAME WHEN 'feedback_category' THEN 'feedback-category' WHEN 'feedback_severity' THEN 'feedback-severity' ELSE NULL END; IF OLD.active AND NOT NEW.active AND expected_scope IS NOT NULL AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind=expected_scope AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active feedback default cannot be deactivated'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_feedback_category_default_deactivation ON feedback_category;
CREATE TRIGGER catalog_feedback_category_default_deactivation BEFORE UPDATE OF active ON feedback_category FOR EACH ROW EXECUTE FUNCTION catalog_prevent_active_feedback_default_deactivation();
DROP TRIGGER IF EXISTS catalog_feedback_severity_default_deactivation ON feedback_severity;
CREATE TRIGGER catalog_feedback_severity_default_deactivation BEFORE UPDATE OF active ON feedback_severity FOR EACH ROW EXECUTE FUNCTION catalog_prevent_active_feedback_default_deactivation();
CREATE OR REPLACE FUNCTION catalog_validate_social_event_default() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT NEW.active OR NEW.scope_kind<>'social-event' THEN RETURN NEW; END IF; IF NEW.scope_id<>'global' OR NEW.locale_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN event_type item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='event_type' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) THEN RAISE EXCEPTION 'social-event default must reference an active published non-deprecated event type'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_social_event_default_integrity ON catalog_scoped_default;
CREATE TRIGGER catalog_social_event_default_integrity BEFORE INSERT OR UPDATE OF catalog_id, entity_id, scope_kind, scope_id, locale_id, active ON catalog_scoped_default FOR EACH ROW EXECUTE FUNCTION catalog_validate_social_event_default();
CREATE OR REPLACE FUNCTION catalog_prevent_active_social_event_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind='social-event' AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active social-event default cannot be deactivated'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_social_event_default_deactivation ON event_type;
CREATE TRIGGER catalog_social_event_default_deactivation BEFORE UPDATE OF active ON event_type FOR EACH ROW EXECUTE FUNCTION catalog_prevent_active_social_event_default_deactivation();
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_event_moment_reaction_type') THEN ALTER TABLE event_moment_reaction ADD CONSTRAINT fk_event_moment_reaction_type FOREIGN KEY (reaction_type_id) REFERENCES reaction_type(id) NOT VALID; END IF; END $$;
ALTER TABLE event_moment_reaction VALIDATE CONSTRAINT fk_event_moment_reaction_type;
CREATE UNIQUE INDEX IF NOT EXISTS uq_event_moment_reaction_identity ON event_moment_reaction (moment_id, reaction_type_id, reactor_party_id) WHERE reaction_type_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_event_moment_reaction_type ON event_moment_reaction (reaction_type_id, created_at DESC);
CREATE OR REPLACE FUNCTION catalog_validate_event_moment_reaction() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.reaction IS NOT NULL OR NEW.reaction_type_id IS NULL THEN RAISE EXCEPTION 'event moment reactions require reaction_type_id and reject copied reaction strings' USING ERRCODE='23514'; END IF; IF NOT EXISTS (SELECT 1 FROM reaction_type item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='reaction-types' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id AND state.code='published' AND state.active WHERE item.id=NEW.reaction_type_id AND item.active AND item.deprecated_at IS NULL) THEN RAISE EXCEPTION 'event moment reaction requires an active published reaction type' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS event_moment_reaction_catalog_integrity ON event_moment_reaction;
CREATE TRIGGER event_moment_reaction_catalog_integrity BEFORE INSERT OR UPDATE OF reaction_type_id, reaction ON event_moment_reaction FOR EACH ROW EXECUTE FUNCTION catalog_validate_event_moment_reaction();
CREATE OR REPLACE FUNCTION catalog_protect_referenced_reaction_type() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.catalog_id IS DISTINCT FROM OLD.catalog_id OR NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'referenced reaction type catalog and code are immutable' USING ERRCODE='23514'; END IF; IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM event_moment_reaction reaction WHERE reaction.reaction_type_id=OLD.id) THEN RAISE EXCEPTION 'a referenced reaction type must be replaced before deactivation' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_reaction_type_reference_protection ON reaction_type;
CREATE TRIGGER catalog_reaction_type_reference_protection BEFORE UPDATE OF catalog_id, code, active ON reaction_type FOR EACH ROW EXECUTE FUNCTION catalog_protect_referenced_reaction_type();
CREATE OR REPLACE FUNCTION catalog_validate_fan_club_content_reaction() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM content_reaction_type item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='content-reaction-types' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id AND state.code='published' AND state.active WHERE item.id=NEW.reaction_type_id AND item.active AND item.deprecated_at IS NULL) THEN RAISE EXCEPTION 'fan club reaction requires an active published content reaction type' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_fan_club_post_reaction_type') THEN ALTER TABLE fan_club_post_reaction ADD CONSTRAINT fk_fan_club_post_reaction_type FOREIGN KEY (reaction_type_id) REFERENCES content_reaction_type(id) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_fan_club_memory_reaction_type') THEN ALTER TABLE fan_club_memory_reaction ADD CONSTRAINT fk_fan_club_memory_reaction_type FOREIGN KEY (reaction_type_id) REFERENCES content_reaction_type(id) NOT VALID; END IF; END $$;
ALTER TABLE fan_club_post_reaction VALIDATE CONSTRAINT fk_fan_club_post_reaction_type;
ALTER TABLE fan_club_memory_reaction VALIDATE CONSTRAINT fk_fan_club_memory_reaction_type;
CREATE INDEX IF NOT EXISTS ix_fan_club_post_reaction_type ON fan_club_post_reaction (reaction_type_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_fan_club_memory_reaction_type ON fan_club_memory_reaction (reaction_type_id, created_at DESC);
DROP TRIGGER IF EXISTS fan_club_post_reaction_catalog_integrity ON fan_club_post_reaction;
CREATE TRIGGER fan_club_post_reaction_catalog_integrity BEFORE INSERT OR UPDATE OF reaction_type_id ON fan_club_post_reaction FOR EACH ROW EXECUTE FUNCTION catalog_validate_fan_club_content_reaction();
DROP TRIGGER IF EXISTS fan_club_memory_reaction_catalog_integrity ON fan_club_memory_reaction;
CREATE TRIGGER fan_club_memory_reaction_catalog_integrity BEFORE INSERT OR UPDATE OF reaction_type_id ON fan_club_memory_reaction FOR EACH ROW EXECUTE FUNCTION catalog_validate_fan_club_content_reaction();
CREATE OR REPLACE FUNCTION catalog_protect_referenced_content_reaction_type() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.catalog_id IS DISTINCT FROM OLD.catalog_id OR NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'referenced content reaction type catalog and code are immutable' USING ERRCODE='23514'; END IF; IF OLD.active AND NOT NEW.active AND (EXISTS (SELECT 1 FROM fan_club_post_reaction reaction WHERE reaction.reaction_type_id=OLD.id) OR EXISTS (SELECT 1 FROM fan_club_memory_reaction reaction WHERE reaction.reaction_type_id=OLD.id)) THEN RAISE EXCEPTION 'a referenced content reaction type must be replaced before deactivation' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS catalog_content_reaction_type_reference_protection ON content_reaction_type;
CREATE TRIGGER catalog_content_reaction_type_reference_protection BEFORE UPDATE OF catalog_id, code, active ON content_reaction_type FOR EACH ROW EXECUTE FUNCTION catalog_protect_referenced_content_reaction_type();
DROP TRIGGER IF EXISTS catalog_no_hard_delete ON content_reaction_type;
CREATE TRIGGER catalog_no_hard_delete BEFORE DELETE ON content_reaction_type FOR EACH ROW EXECUTE FUNCTION catalog_prevent_hard_delete();
