      WHEN service_kind = 'Mastering' AND tier = 'Pro' THEN 3
      WHEN service_kind = 'Mastering' AND tier = 'Premium' THEN 5
      WHEN service_kind = 'Bundle' AND tier = 'Pro' THEN 3
      WHEN service_kind = 'Bundle' AND tier = 'Premium' THEN 5
    END;

