    SELECT 1 FROM public.tdf_schema_migration
    WHERE migration_id = '2026-09-07_artist_merch_storefronts'
      AND checksum NOT IN ('699100a59dc180e12cc0c13d5053a6aab002c9ff891672411ac6ea3d67f771db')
