\endif

\unset run_code
\unset safety_threshold
\unset batch_size
\unset backfill_run_id
\unset records_backfill_run_id
\echo Checking 2026-09-28_interaction_policy
DO $checksum$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.tdf_schema_migration
    WHERE migration_id = '2026-09-28_interaction_policy'
      AND checksum NOT IN ('bdb8004b8af80a16f0073cdb4372f45708aaddcb13e2d859926bfd0156f53efc')
  ) THEN
    RAISE EXCEPTION 'Checksum mismatch for migration 2026-09-28_interaction_policy';
  END IF;
