    SELECT 1 FROM public.tdf_schema_migration
    WHERE migration_id = '2026-09-29_interaction_legacy_reply_aliases'
      AND checksum NOT IN ('deb0d1e81b15c1cf29d11730b9421fa42a4c01db09b8ee2eda65841e7fc0e02e')
  ) THEN
    RAISE EXCEPTION 'Checksum mismatch for migration 2026-09-29_interaction_legacy_reply_aliases';
  END IF;
