    SELECT 1 FROM public.tdf_schema_migration
    WHERE migration_id = '2026-09-29_interaction_catalog_authority'
      AND checksum NOT IN ('da57327773268a24dd6909e948d3cc4882eca9b52912b7a18894c05ce75f20b4')
  ) THEN
