   SELECT coalesce(array_agg(DISTINCT (x->>'partyId')::bigint),'{}'::bigint[]) INTO new_mentions
   FROM jsonb_array_elements(mentions) x WHERE NOT EXISTS(SELECT 1 FROM interaction_comment_mention m
