SELECT NOT EXISTS (SELECT 1 FROM public.tdf_schema_migration WHERE migration_id = '2026-10-03_discovery_ownership_metadata_boundary') AS apply_migration_160 \gset
\if :apply_migration_160
\echo Applying migration 2026-10-03_discovery_ownership_metadata_boundary
-- Accept the private ingestion snapshot while preserving every public metadata
